$cntQ = $pdo->prepare('SELECT COUNT(*) FROM avaliacao_questoes WHERE avaliacao_id = ?');
$insQ = $pdo->prepare('INSERT INTO avaliacao_questoes (avaliacao_id, enunciado, ordem) VALUES (?, ?, ?)');
